	return 0;
}

 static __u8 *ch_report_fixup(struct hid_device *hdev, __u8 *rdesc,
 		unsigned int *rsize)
 {
	if (*rsize >= 17 && rdesc[11] == 0x3c && rdesc[12] == 0x02) {
 		hid_info(hdev, "fixing up Cherry Cymotion report descriptor\n");
 		rdesc[11] = rdesc[16] = 0xff;
 		rdesc[12] = rdesc[17] = 0x03;
	}
	return rdesc;
}

 static __u8 *pl_report_fixup(struct hid_device *hdev, __u8 *rdesc,
 		unsigned int *rsize)
 {
	if (*rsize >= 60 && rdesc[39] == 0x2a && rdesc[40] == 0xf5 &&
 			rdesc[41] == 0x00 && rdesc[59] == 0x26 &&
 			rdesc[60] == 0xf9 && rdesc[61] == 0x00) {
 		hid_info(hdev, "fixing up Petalynx Maxter Remote report descriptor\n");
		rdesc[60] = 0xfa;
		rdesc[40] = 0xfa;
	}
	return rdesc;
}

xps_load_sfnt_name(xps_font_t *font, char *namep)
 {
     byte *namedata;
     int offset, length;
    /*int format;*/
    int count, stringoffset;
    int found;
    int i, k;

    found = 0;
    strcpy(namep, "Unknown");

    offset = xps_find_sfnt_table(font, "name", &length);
    if (offset < 0 || length < 6)
    {
        gs_warn("cannot find name table");
        return;
    }

    /* validate the offset, and the data for the two
     * values we're about to read
     */
    if (offset + 6 > font->length)
    {
        gs_warn("name table byte offset invalid");
        return;
    }
    namedata = font->data + offset;

    /*format = u16(namedata + 0);*/
    count = u16(namedata + 2);
    stringoffset = u16(namedata + 4);

    if (stringoffset + offset > font->length
        || offset + 6 + count * 12 > font->length)
    {
        gs_warn("name table invalid");
        return;
    }

    if (length < 6 + (count * 12))
    {
        gs_warn("name table too short");
        return;
    }

    for (i = 0; i < count; i++)
    {
        byte *record = namedata + 6 + i * 12;
        int pid = u16(record + 0);
        int eid = u16(record + 2);
        int langid = u16(record + 4);
        int nameid = u16(record + 6);
         length = u16(record + 8);
         offset = u16(record + 10);

         /* Full font name or postscript name */
         if (nameid == 4 || nameid == 6)
         {
                if (found < 3)
                {
                    memcpy(namep, namedata + stringoffset + offset, length);
                    namep[length] = 0;
                    found = 3;
                }
            }

            if (pid == 3 && eid == 1 && langid == 0x409) /* windows unicode ucs-2, US */
            {
                if (found < 2)
                {
                    unsigned char *s = namedata + stringoffset + offset;
                    int n = length / 2;
                    for (k = 0; k < n; k ++)
                    {
                        int c = u16(s + k * 2);
                        namep[k] = isprint(c) ? c : '?';
                    }
                    namep[k] = 0;
                    found = 2;
                }
            }

            if (pid == 3 && eid == 10 && langid == 0x409) /* windows unicode ucs-4, US */
            {
                if (found < 1)
                {
                    unsigned char *s = namedata + stringoffset + offset;
                    int n = length / 4;
                    for (k = 0; k < n; k ++)
                    {
                        int c = u32(s + k * 4);
                        namep[k] = isprint(c) ? c : '?';
                    }
                    namep[k] = 0;
                    found = 1;
                }
            }
        }
    }

get_matching_model_microcode(int cpu, unsigned long start,
			     void *data, size_t size,
			     struct mc_saved_data *mc_saved_data,
			     unsigned long *mc_saved_in_initrd,
			     struct ucode_cpu_info *uci)
{
	u8 *ucode_ptr = data;
	unsigned int leftover = size;
	enum ucode_state state = UCODE_OK;
	unsigned int mc_size;
	struct microcode_header_intel *mc_header;
	struct microcode_intel *mc_saved_tmp[MAX_UCODE_COUNT];
 	unsigned int mc_saved_count = mc_saved_data->mc_saved_count;
 	int i;

	while (leftover) {
 		mc_header = (struct microcode_header_intel *)ucode_ptr;

 		mc_size = get_totalsize(mc_header);
		if (!mc_size || mc_size > leftover ||
			microcode_sanity_check(ucode_ptr, 0) < 0)
			break;

		leftover -= mc_size;

		/*
		 * Since APs with same family and model as the BSP may boot in
		 * the platform, we need to find and save microcode patches
		 * with the same family and model as the BSP.
		 */
		if (matching_model_microcode(mc_header, uci->cpu_sig.sig) !=
			 UCODE_OK) {
			ucode_ptr += mc_size;
			continue;
		}

		_save_mc(mc_saved_tmp, ucode_ptr, &mc_saved_count);

		ucode_ptr += mc_size;
	}

	if (leftover) {
		state = UCODE_ERROR;
		goto out;
	}

	if (mc_saved_count == 0) {
		state = UCODE_NFOUND;
		goto out;
	}

	for (i = 0; i < mc_saved_count; i++)
		mc_saved_in_initrd[i] = (unsigned long)mc_saved_tmp[i] - start;

	mc_saved_data->mc_saved_count = mc_saved_count;
out:
	return state;
}

static s32 svc_parse_slice(GF_BitStream *bs, AVCState *avc, AVCSliceInfo *si)
{
	s32 pps_id;

	/*s->current_picture.reference= h->nal_ref_idc != 0;*/
	gf_bs_read_ue_log(bs, "first_mb_in_slice");
	si->slice_type = gf_bs_read_ue_log(bs, "slice_type");
	if (si->slice_type > 9) return -1;

	pps_id = gf_bs_read_ue_log(bs, "pps_id");
	if (pps_id > 255)
		return -1;
	si->pps = &avc->pps[pps_id];
	si->pps->id = pps_id;
	if (!si->pps->slice_group_count)
		return -2;
	si->sps = &avc->sps[si->pps->sps_id + GF_SVC_SSPS_ID_SHIFT];
	if (!si->sps->log2_max_frame_num)
		return -2;

	si->frame_num = gf_bs_read_int_log(bs, si->sps->log2_max_frame_num, "frame_num");

	si->field_pic_flag = 0;
	if (si->sps->frame_mbs_only_flag) {
		/*s->picture_structure= PICT_FRAME;*/
	}
	else {
		si->field_pic_flag = gf_bs_read_int_log(bs, 1, "field_pic_flag");
		if (si->field_pic_flag) si->bottom_field_flag = gf_bs_read_int_log(bs, 1, "bottom_field_flag");
	}
	if (si->nal_unit_type == GF_AVC_NALU_IDR_SLICE || si->NalHeader.idr_pic_flag)
		si->idr_pic_id = gf_bs_read_ue_log(bs, "idr_pic_id");

	if (si->sps->poc_type == 0) {
		si->poc_lsb = gf_bs_read_int_log(bs, si->sps->log2_max_poc_lsb, "poc_lsb");
		if (si->pps->pic_order_present && !si->field_pic_flag) {
			si->delta_poc_bottom = gf_bs_read_se_log(bs, "delta_poc_bottom");
		}
	}
	else if ((si->sps->poc_type == 1) && !si->sps->delta_pic_order_always_zero_flag) {
		si->delta_poc[0] = gf_bs_read_se_log(bs, "delta_poc0");
		if ((si->pps->pic_order_present == 1) && !si->field_pic_flag)
			si->delta_poc[1] = gf_bs_read_se_log(bs, "delta_poc1");
	}
	if (si->pps->redundant_pic_cnt_present) {
		si->redundant_pic_cnt = gf_bs_read_ue_log(bs, "redundant_pic_cnt");
	}
	return 0;
}

Status BuildFeatureReaders(const OpInputList& ragged_values_list,
                           const OpInputList& ragged_splits_list,
                           const OpInputList& sparse_indices_list,
                           const OpInputList& sparse_values_list,
                           const OpInputList& dense_list, int64 batch_size,
                           FeatureReaders* features) {
  features->reserve(input_order_.size());

  int next_ragged = 0;
  int next_sparse = 0;
  int next_dense = 0;
  for (char c : input_order_) {
    if (c == 'R') {
      TF_RETURN_IF_ERROR(BuildRaggedFeatureReader(
          ragged_values_list[next_ragged], ragged_splits_list[next_ragged],
          features));
      next_ragged++;
    } else if (c == 'S') {
      TF_RETURN_IF_ERROR(BuildSparseFeatureReader(
          sparse_indices_list[next_sparse], sparse_values_list[next_sparse],
          batch_size, features));
      next_sparse++;
    } else if (c == 'D') {
      TF_RETURN_IF_ERROR(
          BuildDenseFeatureReader(dense_list[next_dense++], features));
    } else {
      return errors::InvalidArgument("Unexpected input_order value.");
    }
  }

  return Status::OK();
}

std::shared_ptr<Grammar> perform_core(const char *s, size_t n,
                                      const Rules &rules, std::string &start,
                                      Log log) {
  Data data;
  any dt = &data;
  auto r = g["Grammar"].parse(s, n, dt);

  if (!r.ret) {
    if (log) {
      if (r.message_pos) {
        auto line = line_info(s, r.message_pos);
        log(line.first, line.second, r.message);
      } else {
        auto line = line_info(s, r.error_pos);
        log(line.first, line.second, "syntax error");
      }
    }
    return nullptr;
  }

  auto &grammar = *data.grammar;

  // User provided rules
  for (const auto &x : rules) {
    auto name = x.first;
    bool ignore = false;
    if (!name.empty() && name[0] == '~') {
      ignore = true;
      name.erase(0, 1);
    }
    if (!name.empty()) {
      auto &rule = grammar[name];
      rule <= x.second;
      rule.name = name;
      rule.ignoreSemanticValue = ignore;
    }
  }

  // Check duplicated definitions
  bool ret = data.duplicates.empty();

  for (const auto &x : data.duplicates) {
    if (log) {
      const auto &name = x.first;
      auto ptr = x.second;
      auto line = line_info(s, ptr);
      log(line.first, line.second, "'" + name + "' is already defined.");
    }
  }

  // Check missing definitions
  for (auto &x : grammar) {
    auto &rule = x.second;

    ReferenceChecker vis(*data.grammar, rule.params);
    rule.accept(vis);
    for (const auto &y : vis.error_s) {
      const auto &name = y.first;
      const auto ptr = y.second;
      if (log) {
        auto line = line_info(s, ptr);
        log(line.first, line.second, vis.error_message[name]);
      }
      ret = false;
    }
  }

  if (!ret) { return nullptr; }

  // Link references
  for (auto &x : grammar) {
    auto &rule = x.second;
    LinkReferences vis(*data.grammar, rule.params);
    rule.accept(vis);
  }

  // Check left recursion
  ret = true;

  for (auto &x : grammar) {
    const auto &name = x.first;
    auto &rule = x.second;

    DetectLeftRecursion vis(name);
    rule.accept(vis);
    if (vis.error_s) {
      if (log) {
        auto line = line_info(s, vis.error_s);
        log(line.first, line.second, "'" + name + "' is left recursive.");
      }
      ret = false;
    }
  }

  if (!ret) { return nullptr; }

  // Set root definition
  auto &start_rule = (*data.grammar)[data.start];

  // Check infinite loop
  {
    DetectInfiniteLoop vis(data.start_pos, data.start);
    start_rule.accept(vis);
    if (vis.has_error) {
      if (log) {
        auto line = line_info(s, vis.error_s);
        log(line.first, line.second,
            "infinite loop is detected in '" + vis.error_name + "'.");
      }
      return nullptr;
    }
  }

  // Automatic whitespace skipping
  if (grammar.count(WHITESPACE_DEFINITION_NAME)) {
    for (auto &x : grammar) {
      auto &rule = x.second;
      auto ope = rule.get_core_operator();
      if (IsLiteralToken::check(*ope)) { rule <= tok(ope); }
    }

    start_rule.whitespaceOpe =
        wsp((*data.grammar)[WHITESPACE_DEFINITION_NAME].get_core_operator());
  }

  // Word expression
  if (grammar.count(WORD_DEFINITION_NAME)) {
    start_rule.wordOpe =
        (*data.grammar)[WORD_DEFINITION_NAME].get_core_operator();
  }

  // Apply instructions
  for (const auto &item : data.instructions) {
    const auto &name = item.first;
    const auto &instruction = item.second;
    auto &rule = grammar[name];

    if (instruction.type == "precedence") {
      const auto &info =
          any_cast<PrecedenceClimbing::BinOpeInfo>(instruction.data);

      if (!apply_precedence_instruction(rule, info, s, log)) {
        return nullptr;
      }
    }
  }

  // Set root definition
  start = data.start;

  return data.grammar;
}

static GF_Err av1dmx_parse_flush_sample(GF_Filter *filter, GF_AV1DmxCtx *ctx)
{
	u32 pck_size;
	GF_FilterPacket *pck;
	u8 *output;

	gf_bs_get_content_no_truncate(ctx->state.bs, &ctx->state.frame_obus, &pck_size, &ctx->state.frame_obus_alloc);

	if (!pck_size) {
		GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[AV1Dmx] no frame OBU, skipping OBU\n"));
		return GF_OK;
	}

	pck = gf_filter_pck_new_alloc(ctx->opid, pck_size, &output);
	if (ctx->src_pck) gf_filter_pck_merge_properties(ctx->src_pck, pck);

	gf_filter_pck_set_cts(pck, ctx->cts);
	gf_filter_pck_set_sap(pck, ctx->state.frame_state.key_frame ? GF_FILTER_SAP_1 : 0);

	memcpy(output, ctx->state.frame_obus, pck_size);

	if (ctx->deps) {
		u8 flags = 0;
		//dependsOn
		flags = ( ctx->state.frame_state.key_frame) ? 2 : 1;
		flags <<= 2;
		//dependedOn
	 	flags |= ctx->state.frame_state.refresh_frame_flags ? 1 : 2;
		flags <<= 2;
		//hasRedundant
	 	//flags |= ctx->has_redundant ? 1 : 2;
	 	gf_filter_pck_set_dependency_flags(pck, flags);
	}

	gf_filter_pck_send(pck);

	av1dmx_update_cts(ctx);
	gf_av1_reset_state(&ctx->state, GF_FALSE);

	return GF_OK;

}

void M_LoadDefaults (void)
{
    int		i;
    int		len;
    FILE*	f;
    char	def[80];
    char	strparm[100];
    char*	newstring;
    int		parm;
    boolean	isstring;

    // set everything to base values
    numdefaults = sizeof(defaults)/sizeof(defaults[0]);
    for (i=0 ; i<numdefaults ; i++)
	*defaults[i].location = defaults[i].defaultvalue;

    // check for a custom default file
    i = M_CheckParm ("-config");
    if (i && i<myargc-1)
    {
	defaultfile = myargv[i+1];
	printf ("	default file: %s\n",defaultfile);
    }
    else
	defaultfile = basedefault;

    // read the file in, overriding any set defaults
    f = fopen (defaultfile, "r");
    if (f)
    {
	while (!feof(f))
	{
	    isstring = false;
	    if (fscanf (f, "%79s %[^\n]\n", def, strparm) == 2)
	    {
		if (strparm[0] == '"')
		{
		    // get a string default
		    isstring = true;
		    len = strlen(strparm);
		    newstring = (char *) malloc(len);
		    strparm[len-1] = 0;
		    strcpy(newstring, strparm+1);
		}
		else if (strparm[0] == '0' && strparm[1] == 'x')
		    sscanf(strparm+2, "%x", &parm);
		else
		    sscanf(strparm, "%i", &parm);
		for (i=0 ; i<numdefaults ; i++)
		    if (!strcmp(def, defaults[i].name))
		    {
			if (!isstring)
			    *defaults[i].location = parm;
			else
			    *defaults[i].location =
				(int) newstring;
			break;
		    }
	    }
	}

	fclose (f);
    }

    for (i = 0; i < numdefaults; i++)
    {
        if (defaults[i].scantranslate)
        {
            parm = *defaults[i].location;
            defaults[i].untranslated = parm;
            *defaults[i].location = scantokey[parm];
        }
    }
}

void CleanWriters(GF_List *writers)
{
